begin;
alter table public.user_app_settings add column if not exists notification_preferences jsonb not null default '{}'::jsonb;
create or replace function public.get_notification_preferences() returns jsonb language sql stable security invoker set search_path=public as $$ select coalesce(notification_preferences,'{}'::jsonb) from public.user_app_settings where user_id=(select auth.uid()); $$;
create or replace function public.set_notification_preferences(p_preferences jsonb) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v jsonb; begin if jsonb_typeof(coalesce(p_preferences,'{}'::jsonb))<>'object' then raise exception 'notification preferences must be a JSON object'; end if; v=jsonb_build_object('likes',coalesce((p_preferences->>'likes')::boolean,true),'comments',coalesce((p_preferences->>'comments')::boolean,true),'mentions',coalesce((p_preferences->>'mentions')::boolean,true),'follows',coalesce((p_preferences->>'follows')::boolean,true),'friend_requests',coalesce((p_preferences->>'friend_requests')::boolean,true),'messages',coalesce((p_preferences->>'messages')::boolean,true),'calls',coalesce((p_preferences->>'calls')::boolean,true),'rooms',coalesce((p_preferences->>'rooms')::boolean,true),'coins',coalesce((p_preferences->>'coins')::boolean,true),'purchases',coalesce((p_preferences->>'purchases')::boolean,true),'announcements',coalesce((p_preferences->>'announcements')::boolean,true),'system',coalesce((p_preferences->>'system')::boolean,true)); insert into public.user_app_settings(user_id,notification_preferences,updated_at) values((select auth.uid()),v,now()) on conflict(user_id) do update set notification_preferences=excluded.notification_preferences,updated_at=now(); return v; end; $$;
create or replace function public.cleanup_expired_notifications(p_limit integer default 5000) returns integer language plpgsql security invoker set search_path=public as $$ declare v_count integer; begin delete from public.notifications where id in(select id from public.notifications where expires_at is not null and expires_at<=now() order by expires_at asc limit least(greatest(coalesce(p_limit,5000),1),20000)); get diagnostics v_count=row_count; return v_count; end; $$;
revoke execute on function public.get_notification_preferences(),public.set_notification_preferences(jsonb),public.cleanup_expired_notifications(integer) from public,anon,authenticated;
grant execute on function public.get_notification_preferences(),public.set_notification_preferences(jsonb) to authenticated;
commit;
